// Package layout holds Go views of the C structures YANET keeps in shared
// memory, generated by shmgen from the DWARF of the dataplane binary.
//
// The views apply only to the architecture of the binary they were
// generated from, one file per architecture: the layouts differ, arm64
// builds align to 128-byte cache lines where amd64 builds align to 64.
//
// The -local list names the pointers the dataplane stores as absolute
// addresses of its own process, and -relative the abs_ pointers the
// control plane stores relative; nothing in the C declarations says so.
//
// The arm64 views come from a release build in build-arm64, configured as
// the arm64 CI job configures build; on an amd64 host it runs in the CI
// image under emulation with -Ddataplane_only=true.
package layout

//go:generate go run ../cmd/shmgen -binary ../../../build/dataplane/yanet-dataplane -package layout -import github.com/yanet-platform/yanet2/controlplane/native/layout -out layout_amd64.go -test layout_amd64_test.go -local dp_worker.iterations,dp_worker.rx_count,dp_worker.rx_size,dp_worker.tx_count,dp_worker.tx_size,dp_worker.remote_rx_count,dp_worker.remote_tx_count,dp_worker.local_tx_drops,dp_worker.remote_tx_drops,dp_worker.rx_chained_drops,dp_worker.disposed_count,dp_worker.rx_mempool,dp_worker.rx_bursts -relative module_ectx.abs_runtime_counter_storages dp_config cp_config cp_config_gen agent cp_module dp_worker decap_module_config classify_attr_line classify_attr_port
//go:generate go run ../cmd/shmgen -binary ../../../build-arm64/dataplane/yanet-dataplane -package layout -import github.com/yanet-platform/yanet2/controlplane/native/layout -out layout_arm64.go -test layout_arm64_test.go -local dp_worker.iterations,dp_worker.rx_count,dp_worker.rx_size,dp_worker.tx_count,dp_worker.tx_size,dp_worker.remote_rx_count,dp_worker.remote_tx_count,dp_worker.local_tx_drops,dp_worker.remote_tx_drops,dp_worker.rx_chained_drops,dp_worker.disposed_count,dp_worker.rx_mempool,dp_worker.rx_bursts -relative module_ectx.abs_runtime_counter_storages dp_config cp_config cp_config_gen agent cp_module dp_worker decap_module_config classify_attr_line classify_attr_port
